mapper.select:
SELECT null as tradeId, bcid.BOOKSET_ID prodId, fp.FINPROD_ABBR prodAbbr, case when lay.prod_style is null then '' else bcid.FINPROD_ID end as layFinprodId, lay.prod_style prodStyle, fadd.is_lay isLay, bcid.BOOK_DATE coveringDate, facr.CAWLBACK_RULE coveringWay, bcid.CLAWBACK_AMT actualAmount, bci.clawback_type AS coveringForm, null covCycleEndDate, null covCycleStartDate, '01' tradeStatus, bci.CLAWBACK_AMT theoryAmount, null ccy FROM BOK_CLAWBACK_INFO_DETAIL bcid INNER JOIN BOK_CLAWBACK_INFO bci ON bci.BOOKSET_ID=bcid.BOOKSET_ID AND bci.LAYERING_ID=bcid.LAYERING_ID AND bci.HAPPEN_DATE=bcid.HAPPEN_DATE AND bci.BOOK_DATE=bcid.BOOK_DATE LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID=bci.BOOKSET_ID LEFT JOIN FIN_PRODUCT_ADD fadd ON fp.FINPROD_ID = fadd.FINPROD_ID INNER JOIN FIN_CASH_INFO fci ON fci.FINPROD_ID = bci.FINPROD_ID AND fci.FINPROD_TYPE=#{COMMON_BUSINESS_TYPE_01} and fci.CASH_TYPE_1=#{CASH_TYPE_1_06} AND fci.CASH_TYPE_2=#{CASH_TYPE_2_C11} INNER JOIN FIN_CLAWBACK_CALC_RULE facr ON facr.CASH_ID=fci.CASH_ID AND facr.EFF_DATE= ( SELECT MAX(f1.EFF_DATE) FROM FIN_CLAWBACK_CALC_RULE f1 WHERE f1.CASH_ID=fci.CASH_ID AND f1.EFF_DATE<=bci.HAPPEN_DATE) LEFT JOIN prd_layer_param lay on lay.finprod_id = bcid.finprod_id where 1=1 and bci.clawback_type = #{ANAPLEROTIC_TYPE_02}
and bcid.BOOKSET_ID in
#{item}
and bcid.finprod_id in
#{item}
and bcid.BOOK_DATE between STR_TO_DATE(#{coveringDateStart}, '%Y-%m-%d') and STR_TO_DATE(#{coveringDateEnd}, '%Y-%m-%d')
and bci.CLAWBACK_TYPE = #{coveringForm}
and facr.CAWLBACK_RULE = #{coveringWay}
and '01' = #{tradeStatus}
UNION ALL
SELECT tfrdt.TOTLE_TRADE_ID as tradeId, fp.FINPROD_ID prodId, fp.FINPROD_ABBR prodAbbr, case when fpa.is_lay = 'Y' then tpd.finprod_id else '' end layFinprodId, lay.prod_style prodStyle, fpa.is_lay isLay, tfrdt.TRADE_DATE coveringDate, facr.CAWLBACK_RULE coveringWay, tfrdt.INT_AMT actualAmount, '01' as coveringForm, tfrdt.Mdate covCycleEndDate, tfrdt.Vdate covCycleStartDate, tfrdt.TRADE_STATUS tradeStatus, null theoryAmount, tfrdt.CCY ccy FROM TRD_FIN_PRODUCT_DEAL_TOTAL tfrdt INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID=tfrdt.FINPROD_ID AND fp.P_FINPROD_ID IS NULL INNER JOIN FIN_PRODUCT_ADD fpa ON fpa.finprod_id = fp.finprod_id INNER JOIN TRD_PRODUCT_DEAL tpd ON tpd.totle_trade_id = tfrdt.totle_trade_id INNER JOIN FIN_CASH_INFO fci ON fci.FINPROD_ID = tpd.finprod_id AND fci.FINPROD_TYPE=#{COMMON_BUSINESS_TYPE_01} and fci.CASH_TYPE_1=#{CASH_TYPE_1_06} AND fci.CASH_TYPE_2=#{CASH_TYPE_2_C11} INNER JOIN FIN_CLAWBACK_CALC_RULE facr ON facr.CASH_ID=fci.CASH_ID AND facr.EFF_DATE=(SELECT MAX(f1.EFF_DATE) FROM FIN_CLAWBACK_CALC_RULE f1 WHERE f1.CASH_ID=fci.CASH_ID AND f1.EFF_DATE<=tfrdt.TRADE_DATE) and not exists ( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL b where b.P_TRADE_ID = tfrdt.Totle_trade_id ) LEFT JOIN prd_layer_param lay on lay.finprod_id = tpd.finprod_id where 1=1 and tfrdt.BUSI_TYPE = #{BUSI_TYPE_31} and tfrdt.PS=#{PS_C16}
and fp.FINPROD_ID in
#{item}
and tpd.finprod_id in
#{item}
and tfrdt.TRADE_DATE between STR_TO_DATE(#{coveringDateStart}, '%Y-%m-%d') and STR_TO_DATE(#{coveringDateEnd}, '%Y-%m-%d')
and '01' = #{coveringForm}
and facr.CAWLBACK_RULE = #{coveringWay}
and tfrdt.TRADE_STATUS = #{tradeStatus}

select * from ( SELECT fci.CCY ccy, facr.CAWLBACK_RULE coveringWay, facr.CAWLBACK_TYPE coveringForm,
fca.ACCR_STR_DATE covCycleStartDate, fca.ACCR_END_DATE covCycleEndDate
#{currentDate} covCycleStartDate, #{currentDate} covCycleEndDate
from FIN_CASH_INFO fci inner join FIN_CLAWBACK_CALC_RULE facr on facr.CASH_ID=fci.CASH_ID
inner join FIN_FLOAT_ACCRUAL_SCHE fca on fca.CASH_ID=fci.CASH_ID
where 1=1 and fci.CASH_TYPE_1=#{CASH_TYPE_1_06} and fci.CASH_TYPE_2=#{CASH_TYPE_2_C11} and fci.FINPROD_TYPE=#{COMMON_BUSINESS_TYPE_01} and facr.CAWLBACK_TYPE = #{ANAPLEROTIC_TYPE_01}
and fci.FINPROD_ID=#{prodId}
and fca.ACCR_END_DATE <= STR_TO_DATE(#{dates}, '%Y-%m-%d') Order by fca.ACCR_END_DATE desc
) where LIMIT 1
